-- Testdaten: belebter Feed. Alles mit Präfix seed: (Profile), act-s- (Treffen), jr-s- (Anfragen), idea-s- (Ideen).
-- Fotos: KI-generiert (public/seed/avatars/, public/activities/{museum,jam,foto,tandem,gassi}.jpg), keine echten Personen.
-- Termine bleiben frisch über seed_schedule (siehe src/lib/meeqo/seed-refresh.ts). Entfernen: siehe MEEQO-UEBERGABE.md.

create table if not exists seed_schedule (activity_id text primary key, offset_min integer not null, period_days integer not null);
on conflict (user_id) do nothing;
on conflict (id) do nothing;
on conflict (activity_id) do nothing;
on conflict do nothing;
on conflict (id) do nothing;
on conflict do nothing;
