insert into activities (id, host_id, title, description, category, intent, place_name, city, lat, lng, starts_at, spots, image_url, booking_mode, public_place, duration_min, min_people) values
  ('act-s-lauf', 'seed:tim', 'Feierabendlauf durch den Schlossgarten', 'Fünf Kilometer, Gesprächstempo. Treffpunkt am Haupteingang, wir warten auf alle.', 'Sport · Laufen', 'friends', 'Schlossgarten, Haupteingang', 'Karlsruhe', 49.0136, 8.4044, date_trunc('minute', now()) + interval '45 minutes', 8, '/activities/garden.jpg', 'request', true, 60, 3),
  ('act-s-yoga', 'seed:selin', 'Yoga im Stadtgarten', 'Matte mitbringen, alle Level. Danach bleibt, wer mag, noch auf einen Tee.', 'Sport · Yoga', 'friends', 'Stadtgarten, Wiese am See', 'Karlsruhe', 49.002, 8.399, date_trunc('minute', now()) + interval '1590 minutes', 10, '/activities/calisthenics.jpg', 'request', true, 75, 4),
  ('act-s-pasta', 'seed:marco', 'Pasta selber machen', 'Wir machen Teig, rollen, kochen und essen zusammen. Zutaten teilen wir uns.', 'Essen · Kochen', 'friends', 'Gemeinschaftsküche, Südweststadt', 'Karlsruhe', 49.004, 8.389, date_trunc('minute', now()) + interval '3960 minutes', 6, '/activities/cooking.jpg', 'request', true, 150, 3),
  ('act-s-kaffee', 'seed:hanna', 'Kaffee am Gutenbergplatz', 'Eine Stunde, ein Kaffee, neue Leute. Ich sitze draußen, falls das Wetter mitspielt.', 'Essen · Kaffee', 'friends', 'Gutenbergplatz', 'Karlsruhe', 49.0089, 8.3866, date_trunc('minute', now()) + interval '95 minutes', 5, '/activities/brunch.jpg', 'request', true, 60, 0),
  ('act-s-turmberg', 'seed:felix', 'Turmberg-Runde in Durlach', 'Rund zwei Stunden über den Turmberg, ein Stück durch die Weinberge, zurück zur Bahn.', 'Outdoor · Wandern', 'friends', 'Durlach, Bergbahn Talstation', 'Karlsruhe', 48.9985, 8.487, date_trunc('minute', now()) + interval '4920 minutes', 12, '/activities/garden.jpg', 'request', true, 150, 4),
  ('act-s-spazier', 'seed:aylin', 'Spaziergang im Schlossgarten', 'Eine ruhige Runde, ungefähr 45 Minuten. Wer neu in der Stadt ist, ist genau richtig.', 'Outdoor · Spaziergang', 'friends', 'Schlossplatz, Pyramide', 'Karlsruhe', 49.0094, 8.4037, date_trunc('minute', now()) + interval '140 minutes', 6, '/activities/garden.jpg', 'request', true, 50, 0),
  ('act-s-zkm', 'seed:johanna', 'ZKM am Sonntag', 'Wir schauen uns die aktuelle Ausstellung an und reden danach im Café darüber.', 'Kultur · Museum', 'friends', 'ZKM, Lorenzstraße', 'Karlsruhe', 49.0013, 8.3836, date_trunc('minute', now()) + interval '6600 minutes', 6, '/activities/museum.jpg', 'request', true, 120, 3),
  ('act-s-kino', 'seed:david', 'Schauburg: Film, danach Gespräch', 'Wir suchen gemeinsam einen Film aus und gehen danach auf ein Getränk.', 'Kultur · Kino', 'friends', 'Schauburg, Marienstraße', 'Karlsruhe', 49.0024, 8.4057, date_trunc('minute', now()) + interval '2640 minutes', 6, '/activities/museum.jpg', 'request', true, 180, 0),
  ('act-s-quiz', 'seed:lukas', 'Kneipenquiz in der Oststadt', 'Wir bilden ein Team, niemand muss alles wissen. Anfänger ausdrücklich willkommen.', 'Spiele · Quiz', 'friends', 'Gottesauer Platz', 'Karlsruhe', 49.008, 8.423, date_trunc('minute', now()) + interval '4050 minutes', 6, '/activities/games.jpg', 'request', true, 150, 0),
  ('act-s-spiele', 'seed:mei', 'Spieleabend: kurze Spiele', 'Spiele, die man in fünf Minuten erklärt. Ich bringe welche mit, du gern auch.', 'Spiele · Brettspiele', 'friends', 'Café am Ludwigsplatz', 'Karlsruhe', 49.009, 8.399, date_trunc('minute', now()) + interval '8340 minutes', 8, '/activities/games.jpg', 'request', true, 180, 3),
  ('act-s-sauna', 'seed:sabine', 'Sauna im Vierordtbad', 'Entspannt, ohne Programm. Wir treffen uns am Eingang und gehen zusammen rein.', 'Wellness · Sauna', 'friends', 'Vierordtbad, Ettlinger Straße', 'Karlsruhe', 49.001, 8.404, date_trunc('minute', now()) + interval '5340 minutes', 4, '/activities/spa.jpg', 'request', true, 150, 0),
  ('act-s-medi', 'seed:noah', 'Meditation im Botanischen Garten', 'Zwanzig Minuten still sitzen, danach eine kleine Runde durch den Garten.', 'Wellness · Meditation', 'friends', 'Botanischer Garten', 'Karlsruhe', 49.0118, 8.3984, date_trunc('minute', now()) + interval '1920 minutes', 8, '/activities/spa.jpg', 'request', true, 60, 0),
  ('act-s-jam', 'seed:elias', 'Offene Jamsession', 'Bring ein Instrument oder deine Stimme mit. Es geht ums Mitspielen, nicht ums Können.', 'Musik · Jamsession', 'friends', 'Kronenplatz', 'Karlsruhe', 49.0091, 8.4113, date_trunc('minute', now()) + interval '4080 minutes', 10, '/activities/jam.jpg', 'request', true, 150, 4),
  ('act-s-karaoke', 'seed:lea', 'Karaoke in der Gruppe', 'Wir singen in der Gruppe, niemand muss allein ans Mikro.', 'Musik · Karaoke', 'friends', 'Europaplatz', 'Karlsruhe', 49.0098, 8.394, date_trunc('minute', now()) + interval '7020 minutes', 8, '/activities/jam.jpg', 'request', true, 150, 0),
  ('act-s-foto', 'seed:paula', 'Fotowalk durch die Südstadt', 'Wir laufen eine Stunde durch Hinterhöfe und Straßen. Handy reicht völlig.', 'Kreativ · Fotografie', 'friends', 'Werderplatz', 'Karlsruhe', 49.001, 8.411, date_trunc('minute', now()) + interval '165 minutes', 6, '/activities/foto.jpg', 'request', true, 75, 3),
  ('act-s-repair', 'seed:kemal', 'Reparieren statt wegwerfen', 'Bring ein kaputtes Gerät mit, wir schauen zusammen rein. Werkzeug ist da.', 'Kreativ · Handwerk', 'friends', 'Tollhaus, Schlachthof', 'Karlsruhe', 49.0026, 8.425, date_trunc('minute', now()) + interval '8100 minutes', 8, '/activities/foto.jpg', 'request', true, 120, 0),
  ('act-s-tandem', 'seed:sofia', 'Spanisch-Deutsch-Tandem', 'Eine Stunde Spanisch, eine Stunde Deutsch. Jedes Niveau, Kaffee inklusive.', 'Lernen · Sprache', 'friends', 'Stadtbibliothek, Neues Ständehaus', 'Karlsruhe', 49.009, 8.3995, date_trunc('minute', now()) + interval '2520 minutes', 6, '/activities/tandem.jpg', 'request', true, 120, 0),
  ('act-s-gassi', 'seed:jan', 'Gassirunde im Hardtwald', 'Mit oder ohne Hund. Eine Stunde durch den Wald, Bruno freut sich über Gesellschaft.', 'Tiere · Gassi', 'friends', 'Hardtwald, Parkplatz am Schloss', 'Karlsruhe', 49.023, 8.403, date_trunc('minute', now()) + interval '9180 minutes', 8, '/activities/gassi.jpg', 'request', true, 60, 0)
